// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ExportConfig Servers and projects as a YAML file, without secrets
	// (GET /api/v1/config)
	ExportConfig(ctx context.Context, request ExportConfigRequestObject) (ExportConfigResponseObject, error)
	// ImportConfig Add the servers and projects of a YAML file that the viewer does not have yet
	// (POST /api/v1/config)
	ImportConfig(ctx context.Context, request ImportConfigRequestObject) (ImportConfigResponseObject, error)
	// GetDesktopSettings Settings of the desktop app (404 in the server)
	// (GET /api/v1/desktop/settings)
	GetDesktopSettings(ctx context.Context, request GetDesktopSettingsRequestObject) (GetDesktopSettingsResponseObject, error)
	// UpdateDesktopSettings Save the settings of the desktop app; they apply at once
	// (PUT /api/v1/desktop/settings)
	UpdateDesktopSettings(ctx context.Context, request UpdateDesktopSettingsRequestObject) (UpdateDesktopSettingsResponseObject, error)
	// GetMessage Get a message with context and backtrace
	// (GET /api/v1/messages/{message_id})
	GetMessage(ctx context.Context, request GetMessageRequestObject) (GetMessageResponseObject, error)
	// GetMessageSource Lines of the source file around the place of a message or a frame of its backtrace
	// (GET /api/v1/messages/{message_id}/source)
	GetMessageSource(ctx context.Context, request GetMessageSourceRequestObject) (GetMessageSourceResponseObject, error)
	// ListProjects List projects
	// (GET /api/v1/projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)
	// CreateProject Add a project
	// (POST /api/v1/projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)
	// DeleteProject Remove a project from the viewer
	// (DELETE /api/v1/projects/{project_id})
	DeleteProject(ctx context.Context, request DeleteProjectRequestObject) (DeleteProjectResponseObject, error)
	// GetProject Get a project
	// (GET /api/v1/projects/{project_id})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)
	// UpdateProject Update a project
	// (PATCH /api/v1/projects/{project_id})
	UpdateProject(ctx context.Context, request UpdateProjectRequestObject) (UpdateProjectResponseObject, error)
	// GetDebuggerState Whether the debugger is on in the project
	// (GET /api/v1/projects/{project_id}/debugger)
	GetDebuggerState(ctx context.Context, request GetDebuggerStateRequestObject) (GetDebuggerStateResponseObject, error)
	// SetDebuggerState Turn the debugger on or off in the project
	// (PUT /api/v1/projects/{project_id}/debugger)
	SetDebuggerState(ctx context.Context, request SetDebuggerStateRequestObject) (SetDebuggerStateResponseObject, error)
	// ImportRequest Add a request from a log format v2 stream, or a log of PHP, Laravel or nginx
	// (POST /api/v1/projects/{project_id}/import)
	ImportRequest(ctx context.Context, request ImportRequestRequestObject) (ImportRequestResponseObject, error)
	// DeleteIngestToken Stop taking pushed logs for the project
	// (DELETE /api/v1/projects/{project_id}/ingest-token)
	DeleteIngestToken(ctx context.Context, request DeleteIngestTokenRequestObject) (DeleteIngestTokenResponseObject, error)
	// CreateIngestToken Make a new push token of the project; the old one stops working
	// (POST /api/v1/projects/{project_id}/ingest-token)
	CreateIngestToken(ctx context.Context, request CreateIngestTokenRequestObject) (CreateIngestTokenResponseObject, error)
	// ClearProjectLogs Delete the project log files on the server and their data in the viewer
	// (DELETE /api/v1/projects/{project_id}/logs)
	ClearProjectLogs(ctx context.Context, request ClearProjectLogsRequestObject) (ClearProjectLogsResponseObject, error)
	// ListRequests Request feed, newest first
	// (GET /api/v1/requests)
	ListRequests(ctx context.Context, request ListRequestsRequestObject) (ListRequestsResponseObject, error)
	// DeleteRequest Delete a request and its log file
	// (DELETE /api/v1/requests/{request_id})
	DeleteRequest(ctx context.Context, request DeleteRequestRequestObject) (DeleteRequestResponseObject, error)
	// GetRequest Get a request (without messages)
	// (GET /api/v1/requests/{request_id})
	GetRequest(ctx context.Context, request GetRequestRequestObject) (GetRequestResponseObject, error)
	// MarkRequest Pin a request or note something about it
	// (PATCH /api/v1/requests/{request_id})
	MarkRequest(ctx context.Context, request MarkRequestRequestObject) (MarkRequestResponseObject, error)
	// ExportRequest The request as a log format v2 stream, to pass it on or import it elsewhere
	// (GET /api/v1/requests/{request_id}/export)
	ExportRequest(ctx context.Context, request ExportRequestRequestObject) (ExportRequestResponseObject, error)
	// ListMessages Request messages in seq order
	// (GET /api/v1/requests/{request_id}/messages)
	ListMessages(ctx context.Context, request ListMessagesRequestObject) (ListMessagesResponseObject, error)
	// ListServers List servers
	// (GET /api/v1/servers)
	ListServers(ctx context.Context, request ListServersRequestObject) (ListServersResponseObject, error)
	// CreateServer Add a server
	// (POST /api/v1/servers)
	CreateServer(ctx context.Context, request CreateServerRequestObject) (CreateServerResponseObject, error)
	// DeleteServer Remove a server and its projects from the viewer
	// (DELETE /api/v1/servers/{server_id})
	DeleteServer(ctx context.Context, request DeleteServerRequestObject) (DeleteServerResponseObject, error)
	// GetServer Get a server
	// (GET /api/v1/servers/{server_id})
	GetServer(ctx context.Context, request GetServerRequestObject) (GetServerResponseObject, error)
	// UpdateServer Update a server
	// (PATCH /api/v1/servers/{server_id})
	UpdateServer(ctx context.Context, request UpdateServerRequestObject) (UpdateServerResponseObject, error)
	// CheckServer Check the server connection
	// (POST /api/v1/servers/{server_id}/check)
	CheckServer(ctx context.Context, request CheckServerRequestObject) (CheckServerResponseObject, error)
	// DiscoverProjects Find projects on a server by the library config (dws_debugger.json)
	// (POST /api/v1/servers/{server_id}/discover)
	DiscoverProjects(ctx context.Context, request DiscoverProjectsRequestObject) (DiscoverProjectsResponseObject, error)
	// TrustHostKey Trust the host key of an SSH server after the user checked its fingerprint
	// (POST /api/v1/servers/{server_id}/host-key)
	TrustHostKey(ctx context.Context, request TrustHostKeyRequestObject) (TrustHostKeyResponseObject, error)
	// GetSettings Get UI settings
	// (GET /api/v1/settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// UpdateSettings Save UI settings; other windows get settings_updated
	// (PUT /api/v1/settings)
	UpdateSettings(ctx context.Context, request UpdateSettingsRequestObject) (UpdateSettingsResponseObject, error)
	// StreamEvents Change stream (Server-Sent Events)
	// (GET /api/v1/stream)
	StreamEvents(ctx context.Context, request StreamEventsRequestObject) (StreamEventsResponseObject, error)
	// GetUpdates Whether a newer version is out (GitHub Releases, asked at most once a day)
	// (GET /api/v1/updates)
	GetUpdates(ctx context.Context, request GetUpdatesRequestObject) (GetUpdatesResponseObject, error)
	// GetVersion Viewer version
	// (GET /api/v1/version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

